function Test-JobCompleteOn {
    <# Succeeded today, per the ledger OR the job's own log. #>
    param(
        [Parameter(Mandatory)]$Job,
        [datetime]$Date = (Get-Date),
        [string]$LedgerPath
    )
    if (Test-LedgerSuccessOn -Id $Job.id -Date $Date -Path $LedgerPath) { return $true }
    $probe = if ($Job.PSObject.Properties['successProbe']) { $Job.successProbe } else { $null }
    Test-Probe -Probe $probe -Date $Date
}
function Test-Probe {
    <#
      Evaluates a job's successProbe / authWarnProbe against its own log output.
      Returns $false when the probe cannot be evaluated (missing file), never throws —
      an unevaluable probe must not be read as success.
    #>
    param(
        $Probe,
        [datetime]$Date = (Get-Date)
    )
    if (-not $Probe) { return $false }
    try {
